import React, { useState } from "react";

// 1. The Sibling Component (Receives state and updater function as props)
function CounterDisplay({ count, onIncrement }) {
  return (
    <div className="p-4 border">
      <h3>Count is: {count}</h3>
      <button onClick={onIncrement}>Increment (Updates Parent)</button>
    </div>
  );
}

// 2. The Sibling Component (Just receives the state)
function WarningMessage({ count }) {
  if (count < 5) return null;
  return <p style={{ color: "red" }}>Warning: Count is getting high!</p>;
}

// 3. The Parent Component (Holds the single source of truth)
export default function ParentApp() {
  const [sharedCount, setSharedCount] = useState(0);

  const handleIncrement = () => {
    setSharedCount(prev => prev + 1);
  };

  return (
    <div>
      <h2>Parent Component</h2>
      {/* We pass the shared state to both siblings! */}
      <CounterDisplay count={sharedCount} onIncrement={handleIncrement} />
      <WarningMessage count={sharedCount} />
    </div>
  );
}
